using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly.
JsonTypeInfo<int[]> arrayInfo = (JsonTypeInfo<int[]>)options.GetTypeInfo(typeof(int[]));
Console.WriteLine($"Typed metadata for int[]: {arrayInfo.Type.Name}");

string json = JsonSerializer.Serialize(new[] { 1, 2, 3 }, arrayInfo);
Console.WriteLine($"Serialised with typed info: {json}");

// 2) Probe without throwing — TryGetTypeInfo returns false instead of an exception.
if (options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? stringInfo))
{
    Console.WriteLine($"Metadata for string found: {stringInfo!.Type.Name}");
}
else
{
    Console.WriteLine("Metadata for string NOT available.");
}

// Demonstrate the "not available" branch using a resolver that knows nothing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => { if (ti.Type == typeof(double)) throw new NotSupportedException(); } }
    }
};

// Pre-warm so the resolver runs (TryGetTypeInfo won't throw; it catches resolver failures).
if (limited.TryGetTypeInfo(typeof(double), out JsonTypeInfo? doubleInfo))
{
    Console.WriteLine($"Metadata for double found: {doubleInfo!.Type.Name}");
}
else
{
    Console.WriteLine("Metadata for double NOT available (expected).");
}

