// A resolver that only provides metadata for System.Int32.
class PartialResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(int) ? _inner.GetTypeInfo(type, options) : null;
}

